t\",{\"href\":\"/en/search/synonyms/?original=mat\",\"children\":[\"$\",\"em\",null,{\"children\":\"mat\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-yājī\",{\"href\":\"/en/search/synonyms/?original=yājī\",\"children\":[\"$\",\"em\",null,{\"children\":\"yājī\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"My worshiper\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-4\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-mām\",{\"href\":\"/en/search/synonyms/?original=mām\",\"children\":[\"$\",\"em\",null,{\"children\":\"mām\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"unto Me\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-5\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-namaskuru\",{\"href\":\"/en/search/synonyms/?original=namaskuru\",\"children\":[\"$\",\"em\",null,{\"children\":\"namaskuru\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"offer your obeisances\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-6\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-mām\",{\"href\":\"/en/search/synonyms/?original=mām\",\"children\":[\"$\",\"em\",null,{\"children\":\"mām\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"unto Me\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-7\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-eva\",{\"href\":\"/en/search/synonyms/?original=eva\",\"children\":[\"$\",\"em\",null,{\"children\":\"eva\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"certainly\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-8\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-eṣyasi\",{\"href\":\"/en/search/synonyms/?original=eṣyasi\",\"children\":[\"$\",\"em\",null,{\"children\":\"eṣyasi\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"you will come\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-9\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-satyam\",{\"href\":\"/en/search/synonyms/?original=satyam\",\"children\":[\"$\",\"em\",null,{\"children\":\"satyam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"truly\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-10\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-te\",{\"href\":\"/en/search/synonyms/?original=te\",\"children\":[\"$\",\"em\",null,{\"children\":\"te\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"to you\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-11\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-pratijāne\",{\"href\":\"/en/search/synonyms/?original=pratijāne\",\"children\":[\"$\",\"em\",null,{\"children\":\"pratijāne\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"I promise\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-12\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-priyaḥ\",{\"href\":\"/en/search/synonyms/?original=priyaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"priyaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"dear\"}}],\"; \"]}],\"$L31\",\"$L32\"]}]}]]]}]\n"])self.__next_f.push([1,"2d:[\"$\",\"div\",\"4813-translation,4813-translation\",{\"className\":\"av-translation\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Translation\"}],[[\"$\",\"$L29\",\"child-4817\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:3:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"Always think of Me, become My devotee, worship Me and offer your homage unto Me. Thus you will come to Me without fail. I promise you this because you are My very dear friend.\"}}]}]}]]]}]\n"])self.__next_f.push([1,"2e:[\"$\",\"div\",\"4813-purport,4813-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L29\",\"child-4818\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"The most confidential part of knowledge is that one should become a pure devotee of Kṛṣṇa and always think of Him and act for Him. One should not become an official meditator. Life should be so molded that one will always have the chance to think of Kṛṣṇa. One should always act in such a way that all his daily activities are in connection with Kṛṣṇa. He should arrange his life in such a way that throughout the twenty-four hours he cannot but think of Kṛṣṇa. And the Lord’s promise is that anyone who is in such pure Kṛṣṇa consciousness will certainly return to the abode of Kṛṣṇa, where he will be engaged in the association of Kṛṣṇa face to face. This most confidential part of knowledge is spoken to Arjuna because he is the dear friend of Kṛṣṇa. Everyone who follows the path of Arjuna can become a dear friend to Kṛṣṇa and obtain the same perfection as Arjuna.\"}}]}],[\"$\",\"$L29\",\"child-4819\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:1\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"These words stress that one should concentrate his mind upon Kṛṣṇa – the very form with two hands carrying a flute, the bluish boy with a beautiful face and peacock feathers in His hair. There are descriptions of Kṛṣṇa found in the Brahma-saṁhitā and other literatures. One should fix his mind on this original form of Godhead, Kṛṣṇa. One should not even divert his attention to other forms of the Lord. The Lord has multiforms as Viṣṇu, Nārāyaṇa, Rāma, Varāha, etc., but a devotee should concentrate his mind on the form that was present before Arjuna. Concentration of the mind on the form of Kṛṣṇa constitutes the most confidential part of knowledge, and this is disclosed to Arjuna because Arjuna is the most dear friend of Kṛṣṇa’s.\"}}]}]]]}]\n"])self.__next_f.push([1,"33:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"loading\":\"lazy\",\"referrerPolicy\":\"no-referrer\",\"crossOrigin\":\"anonymous\"}]]\n"])self.__next_f.push([1,"26:[\"$\",\"div\",null,{\"id\":\"footer\",\"className\":\"mt-auto w-full max-w-7xl mx-auto pt-3 mb-6 text-sm text-vb-normal-text/80 text-center\",\"children\":[[\"$\",\"$L1f\",null,{\"donors\":\"Shweta Saxena; Gopalakrishnan Soundarajan;    Kuldip Persaud;  Raghava Chandra Dasa; Shubhangi Rajiv Panjiyar; Suparna Kotaru;  Rajendra and Geeta Ramchandani;  Jaykumar Prabhakar; Bharat Vyas; Shri Chander Mohan Gilhotra, HG Prashant Mukund Das, Shri Trilok Singh Grover, HG Bhakta Mitra Das, Laxmi Narayan Agarwal; Ronak Talati; Bhargav Ashok; Akiralali; Rajasa das; Riya and Tejal Chopade; Indradyumna Swami; Jai Devaki Parks;  Ashmi Chakraborty; Hari-kirtana das; Ramesta das; Prasad Buddhavarapu; Kresna Sucandra; Esekiel Jaggernauth\",\"locale\":\"en\"}],[\"$\",\"div\",null,{\"className\":\"w-full max-w-screen-xl mx-auto text-vb-normal-text mb-3\",\"children\":[[\"$\",\"a\",null,{\"targe