0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":4820,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 18.66\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T559,According to the devotional process, one should simply accept such religious principles that will lead ultimately to the devotional service of the Lord. One may perform a particular occupational duty according to his position in the social order, but if by executing his duty one does not come to the point of Kṛṣṇa consciousness, all his activities are in vain. Anything that does not lead to the perfectional stage of Kṛṣṇa consciousness should be avoided. One should be confident that in all circumstances Kṛṣṇa will protect him from all difficulties. There is no need of thinking how one should keep the body and soul together. Kṛṣṇa will see to that. One should always think himself helpless and should consider Kṛṣṇa the only basis for his progress in life. As soon as one seriously engages himself in devotional service to the Lord in full Kṛṣṇa consciousness, at once he becomes freed from all contamination of material nature. There are different processes of religion and purificatory processes by cultivation of knowledge, meditation in the mystic yoga system, etc., but one who surrenders unto Kṛṣṇa does not have to execute so many methods. That simple surrender unto Kṛṣṇa will save him from unnecessarily wasting time. One can thus make all progress at once and be freed from all sinful reactions.26:T4be,One should be attracted by the beautiful vision of Kṛṣṇa. His name is Kṛṣṇa because He is all-attractive. One who becomes attracted by the beautiful, all-powerful, omnipotent vision of Kṛṣṇa is fortunate. There are different kinds of transcendentalists – some of them are attached to the impersonal Brahman vision, some of them are attracted by the Supersoul feature, etc., but one who is attracted to the personal feature of the Supreme Personality of Godhead, and, above all, one who is attracted by the Supreme Personality of Godhead as Kṛṣṇa Himself, is the most perfect transcendentalist. In other words, devotional service to Kṛṣṇa, in full consciousness, is the most confidential part of knowledge, and this is the essence of the whole Bhagavad-gītā. Karma-yogīs, empiric philosophers, mystics and devotees are all called transcendentalists, but one who is a pure devotee is the best of all. The particular words used here, mā śucaḥ, “Don’t fear, don’t hesitate, don’t worry,” are very significant. One may be perplexed as to how one can give up all kinds of religious forms and simply surrender unto Kṛṣṇa, but such worry is useless."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":4820,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"66\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_descri