name\":\"Nederlands (Dutch)\",\"language_code\":\"nl\",\"enabled\":true,\"url_path\":\"/nl/library/bg/18/66/\"},{\"display_name\":\"Polski (Polish)\",\"language_code\":\"pl\",\"enabled\":true,\"url_path\":\"/pl/library/bg/18/66/\"},{\"display_name\":\"Português (Portuguese)\",\"language_code\":\"pt-br\",\"enabled\":true,\"url_path\":\"/pt-br/library/bg/18/66/\"},{\"display_name\":\"Русский (Russian)\",\"language_code\":\"ru\",\"enabled\":true,\"url_path\":\"/ru/library/bg/18/66/\"},{\"display_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/18/66/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/18/66/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/18/66/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/18/\",\"title\":\"Chapter Eighteen: Conclusion – The Perfection of Renunciation\"}],\"url_path\":\"/en/library/bg/18/66/\",\"bb\":4217,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/18/65/\",\"title\":\"TEXT 65\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/18/67/\",\"title\":\"TEXT 67\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":4821,\"bb\":568530,\"url_path\":\"/en/library/bg/18/66/devanagari/\",\"body_final\":\"सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज ।
अहं त्वां सर्वपापेभ्यो मोक्षयिष्यामि मा श‍ुच: ॥ ६६ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4822,\"bb\":4218,\"url_path\":\"/en/library/bg/18/66/b4218/\",\"body_value\":\"sarva-dharmān parityajya
mām ekaṁ śaraṇaṁ vraja
ahaṁ tvāṁ sarva-pāpebhyo
mokṣayiṣyāmi mā śucaḥ\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":4823,\"bb\":4219,\"url_path\":\"/en/library/bg/18/66/b4219/\",\"shadow_value\":\"sarva-dharmān – all varieties of religion; parityajya – abandoning; mām – unto Me; ekam – only; śaraṇam – for surrender; vraja – go; aham – I; tvām – you; sarva – all; pāpebhyaḥ – from sinful reactions; mokṣayiṣyāmi – will deliver; mā – do not; śucaḥ – worry.\",\"word_for_word_value\":[{\"word\":\"sarva-dharmān\",\"translation\":\"all varieties of religion\"},{\"word\":\"parityajya\",\"translation\":\"abandoning\"},{\"word\":\"mām\",\"translation\":\"unto Me\"},{\"word\":\"ekam\",\"translation\":\"only\"},{\"word\":\"śaraṇam\",\"translation\":\"for surrender\"},{\"word\":\"vraja\",\"translation\":\"go\"},{\"word\":\"aham\",\"translation\":\"I\"},{\"word\":\"tvām\",\"translation\":\"you\"},{\"word\":\"sarva\",\"translation\":\"all\"},{\"word\":\"pāpebhyaḥ\",\"translation\":\"from sinful reactions\"},{\"word\":\"mokṣayiṣyāmi\",\"translation\":\"will deliver\"},{\"word\":\"mā\",\"translation\":\"do not\"},{\"word\":\"śucaḥ\",\"translation\":\"worry\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":4824,\"bb\":4220,\"url_path\":\"/en/library/bg/18/66/b4220/\",\"body_value\":\"Abandon all varieties of religion and just surrender unto Me. I shall deliver you from all sinful reactions. Do not fear.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4825,\"bb\":4221,\"url_path\":\"/en/library/bg/18/66/b4221/\",\"body_value\":\"The Lord has described various kinds of knowledge and processes of religion – knowledge of the Supreme Brahman, knowledge of the Supersoul, knowledge of the different types of orders and statuses of social life, knowledge of the renounced order of life, knowledge of nonattachment, sense and mind control, meditation, etc. He has described in so many ways different types of religion. Now, in summarizing Bhagavad-gītā, the Lord says that Arjuna should give up all the processes that have been explained to him; he should simply surrender to Kṛṣṇa. That surrender will save him from all kinds of sinful reactions, for the Lord personally promises to protect him.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4826,\"bb\":4222,\"url_path\":\"/en/library/bg/18/66/b4222/\",\"body_value\":\"In the Seventh Chapter it was said that only one who has become free from all sinful reactions can take to the worship of Lord Kṛṣṇa. Thus one may think that unless he is free from all sinful reactions he cannot take to the surrendering process. To such doubts it is here said that even if one is not free from all sinful reactions, simply by the process of surrendering to Śrī Kṛṣṇa he is automatically freed. There is no need of strenuous effort to free oneself from sinful reactions. One should unhesitatingly accept Kṛṣṇa as the supreme savior of all living entities. With faith and love, one should surrender unto Him.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4827,\"bb\":4223,\"url_path\":\"/en/library/bg/18/66/b4223/\",\"body_value\":\"The process of surrender to Kṛṣṇa is described in the Hari-bhakti-vilāsa (11.676):\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4828,\"bb\":4224,\"url_path\":\"/en/library/bg/18/66/b4224/\",\"body_value\":\"ānukūlyasya saṅkalpaḥ
prātikūlyasya varjanam
rakṣiṣyatīti viśvāso
